   "competencial": false,
   "q": "Describa el ciclo lítico de un bacteriófago [2].",
   "c": [
    "Existencia de <mark class=\"clave-criterio\">receptores específicos</mark> en la superficie de la bacteria a los que se une el fago (0,4 p).",
    "<mark class=\"clave-criterio\">Inyección del ácido nucleico</mark> vírico por la vaina contráctil, o entrada del ácido nucleico junto con la cápsida y posterior pérdida de la cápsida (0,4 p).",
    "Utilización de la <mark class=\"clave-criterio\">maquinaria biosintética de la bacteria</mark> para producir muchas <mark class=\"clave-criterio\">copias del ácido nucleico y de la cápsida</mark>, así como de otros componentes víricos, si los tuviera (0,4 p).",
    "<mark class=\"clave-criterio\">Unión de los componentes</mark> sintetizados, rodeándose cada molécula de ácido nucleico vírico de la correspondiente cápsida (0,4 p).",
    "Rotura de la célula por <mark class=\"clave-criterio\">enzimas líticas</mark> que permiten la salida de los nuevos fagos formados (0,4 p)."
   ],
