   "q": "¿Por qué las bacterias que se encuentran en nuestro cuerpo (intestino, piel, etc.) y que en condiciones normales son inocuas o beneficiosas, pueden en determinadas circunstancias producirnos enfermedades? Razone la respuesta [1].",
   "c": [
    "Si se produce una <mark class=\"clave-criterio\">deficiencia del sistema inmunitario</mark>, disminuyen las defensas y los microorganismos pueden <mark class=\"clave-criterio\">crecer descontroladamente</mark> y ocasionar enfermedades. Se valora cualquier otro razonamiento adecuado: que los microorganismos <mark class=\"clave-criterio\">atraviesen las barreras</mark> donde están confinados, que se altere la <mark class=\"clave-criterio\">composición de la comunidad microbiana</mark>, etc. Basta una respuesta para la máxima nota (1 p)."
   ],
