   "topic": "Respuesta inflamatoria",
   "anio": 2010,
   "hasImg": true,
   "competencial": true,
   "q": "<b>En relación con la figura adjunta, conteste las siguientes cuestiones:</b><br>a) Nombre el proceso general que se representa en la imagen [0,2]. Indique la acción que realiza la célula señalada con el número 1 y el tipo de célula de que se trata [0,2]. Cite dos síntomas característicos de este proceso [0,2]. Describa la acción señalada con el número 2 [0,4].<br>b) Explique las consecuencias de la vasodilatación [0,5]. Indique si este proceso forma parte de las defensas específicas o inespecíficas [0,5].",
   "c": [
    "a) <mark class=\"clave-criterio\">Respuesta inflamatoria</mark> (0,2 p).",
    "a) <mark class=\"clave-criterio\">Fagocitosis</mark> realizada por un fagocito (<mark class=\"clave-criterio\">macrófago o neutrófilo</mark>) (0,2 p).",
    "a) <mark class=\"clave-criterio\">Enrojecimiento</mark>, <mark class=\"clave-criterio\">tumefacción</mark>, <mark class=\"clave-criterio\">dolor</mark>, <mark class=\"clave-criterio\">aumento de temperatura</mark>, etc. Solo dos, a 0,1 p cada uno (0,2 p).",
    "a) Aumento de la <mark class=\"clave-criterio\">permeabilidad capilar</mark> que permite la <mark class=\"clave-criterio\">salida de leucocitos</mark> que se dirigen a la zona infectada (0,4 p).",
    "b) La vasodilatación aumenta el <mark class=\"clave-criterio\">riego sanguíneo</mark> y la afluencia de <mark class=\"clave-criterio\">glóbulos blancos y moléculas defensivas</mark> a la zona afectada. El enrojecimiento se produce por el aumento de la cantidad de sangre en la zona (0,5 p).",
    "b) Es una <mark class=\"clave-criterio\">defensa inespecífica</mark>, porque puede provocarla cualquier antígeno o un traumatismo (0,5 p)."
   ],
