   "topic": "Lípidos saponificables e insaponificables",
   "anio": 2010,
   "hasImg": false,
   "competencial": false,
   "q": "Defina triacilglicérido y fosfolípido [0,8]. Indique las diferencias entre los lípidos saponificables y los insaponificables [0,6], cite un tipo [0,2] y una función de cada uno de ellos [0,4].",
   "c": [
    "Triacilglicérido: <mark class=\"clave-criterio\">éster de glicerina con tres ácidos grasos</mark> (0,4 p).",
    "Fosfolípido: glicerina unida por dos de sus grupos alcohol a dos ácidos grasos por <mark class=\"clave-criterio\">enlace éster</mark>, y por el tercero a un grupo fosfato que se une por enlace éster a un <mark class=\"clave-criterio\">aminoalcohol</mark> o radical polar (0,4 p).",
    "Diferencias: <mark class=\"clave-criterio\">presencia o no de ácidos grasos</mark> y <mark class=\"clave-criterio\">formación de jabones</mark> (0,6 p).",
    "Saponificables: <mark class=\"clave-criterio\">acilglicéridos</mark>, céridos, fosfolípidos y esfingolípidos. Insaponificables: <mark class=\"clave-criterio\">carotenoides</mark> y <mark class=\"clave-criterio\">esteroides</mark>. Un ejemplo de cada tipo, a 0,1 p (0,2 p).",
    "Funciones. Acilglicéridos: <mark class=\"clave-criterio\">energética</mark>; fosfolípidos y esfingolípidos: <mark class=\"clave-criterio\">estructural</mark> (membranas); céridos: <mark class=\"clave-criterio\">protectora</mark>; esteroides: componentes de membranas, precursores de vitaminas y hormonas; carotenoides: <mark class=\"clave-criterio\">antioxidantes</mark>, precursores de vitaminas. Un ejemplo de cada tipo con su función, a 0,2 p (0,4 p)."
   ],
