   "competencial": true,
   "q": "<b>A la vista de la imagen, conteste las siguientes cuestiones:</b><br>a) Indique el nombre del orgánulo o de la estructura celular señalados por cada uno de los números [0,4]. Indique una función de los orgánulos o estructuras 1, 4 y 5 [0,3]. Nombre seis orgánulos celulares cuyas membranas cumplan el modelo de Mosaico Fluido [0,3].<br>b) Nombre dos funciones de la estructura señalada con el número 2 [0,2] y dos de la señalada con el número 7 [0,2]. Indique en qué estructuras u orgánulos celulares, incluidos o no en la figura, se realizan las siguientes actividades celulares: transcripción, traducción, fosforilación oxidativa, glucólisis, respiración y digestión celular [0,6].",
