   "anio": 2011,
   "hasImg": false,
   "competencial": false,
   "q": "Se sabe que el sistema inmunitario reacciona contra todo tipo de molécula que no reconoce como propia. ¿Cuál es la causa de que proteínas extrañas inyectadas por vía sanguínea provoquen la respuesta del sistema inmunológico, mientras que si se toman por vía digestiva, generalmente no la provocan? Razone la respuesta [1].",
