    "Por vía digestiva las proteínas se degradan: los jugos digestivos contienen <mark class=\"clave-criterio\">peptidasas</mark> que rompen enlaces peptídicos y liberan <mark class=\"clave-criterio\">aminoácidos, comunes a todos los seres vivos</mark> (0,5 p).",
    "Por vía sanguínea no hay tal ruptura y, como las proteínas son <mark class=\"clave-criterio\">específicas de cada organismo</mark>, el sistema inmunitario las <mark class=\"clave-criterio\">reconoce como extrañas</mark> y responde contra ellas (0,5 p)."
