    "a) A: <mark class=\"clave-criterio\">energía luminosa</mark>; B: <mark class=\"clave-criterio\">agua</mark>; C: <mark class=\"clave-criterio\">oxígeno</mark>; D: <mark class=\"clave-criterio\">glucosa</mark> (0,4 p).",
