   "topic": "Ruta de secreción de proteínas",
   "anio": 2011,
   "hasImg": false,
   "competencial": false,
   "q": "El biólogo George Palade utilizó aminoácidos marcados con isótopos radioactivos para averiguar la ruta de secreción de proteínas en células pancreáticas. A los 3 minutos de haberle suministrado a las células los aminoácidos marcados éstos se localizaban en el retículo endoplasmático rugoso, a los 20 minutos en el complejo de Golgi y a los 90 minutos en las vesículas secretoras. Justifique por qué aparecen en ese orden [1].",
   "c": [
    "Primero en el <mark class=\"clave-criterio\">RER</mark>, donde tiene lugar la <mark class=\"clave-criterio\">síntesis de proteínas</mark> al poseer <mark class=\"clave-criterio\">ribosomas</mark>; después en el <mark class=\"clave-criterio\">complejo de Golgi</mark>, que <mark class=\"clave-criterio\">completa y ensambla las proteínas destinadas a la secreción</mark>; por último en las <mark class=\"clave-criterio\">vesículas secretoras</mark>, que se <mark class=\"clave-criterio\">fusionan con la membrana plasmática</mark> para liberar su contenido. Una razón 0,3 p; dos, 0,6 p; las tres, 1 p."
   ],
