   "hasImg": true,
   "competencial": true,
   "q": "<b>A la vista del esquema que representa un proceso celular, conteste las siguientes preguntas:</b><br>a) Ordene correctamente las figuras A a F e identifique el proceso celular representado [0,6]. Nombre los elementos señalados con los números 1 y 2 [0,2]. ¿Qué indican las flechas en los esquemas? [0,2].<br>b) Explique el proceso representado [0,5]. Indique el nombre del orgánulo que está implicado en la formación del elemento señalado con el número 1 [0,2]. Indique si este proceso se realiza en células animales, vegetales o en ambas y cite un ejemplo de células que lo realizan [0,3].",
