   "anio": 2010,
   "hasImg": false,
   "competencial": false,
   "q": "Explique la interfase y qué sucede en cada una de las fases en que se subdivide [1]. Defina los siguientes términos: centrómero [0,25], cromátidas hermanas [0,25], bivalente [0,25] y telómeros [0,25].",
   "c": [
    "Interfase: conjunto de fases que transcurren entre <mark class=\"clave-criterio\">dos mitosis consecutivas</mark> (0,25 p).",
    "Fase G1: se sintetizan los compuestos necesarios para que la célula <mark class=\"clave-criterio\">aumente de tamaño</mark> y al mismo tiempo se incrementa el número de <mark class=\"clave-criterio\">orgánulos citoplasmáticos</mark> (0,25 p).",
    "Fase S: <mark class=\"clave-criterio\">replicación del ADN</mark> (0,25 p).",
    "Fase G2: la célula <mark class=\"clave-criterio\">se prepara para la mitosis</mark> (0,25 p).",
    "Centrómero: también llamado <mark class=\"clave-criterio\">constricción primaria</mark>, es un estrechamiento que divide al cromosoma en dos porciones denominadas <mark class=\"clave-criterio\">brazos</mark> (0,25 p).",
    "Cromátidas hermanas: cromátidas que resultan de la <mark class=\"clave-criterio\">duplicación del material genético</mark> y que forman un <mark class=\"clave-criterio\">cromosoma metafásico</mark> (0,25 p).",
    "Bivalente: también llamado <mark class=\"clave-criterio\">tétrada</mark>, es una estructura cromosómica constituida por <mark class=\"clave-criterio\">cuatro cromátidas</mark> que se forma durante la <mark class=\"clave-criterio\">profase I</mark> como resultado del apareamiento gen a gen de los <mark class=\"clave-criterio\">cromosomas homólogos</mark> (0,25 p).",
    "Telómeros: <mark class=\"clave-criterio\">regiones terminales</mark> de los cromosomas (0,25 p)."
   ],
