    "Inmunodeficiencia: <mark class=\"clave-criterio\">incapacidad del sistema inmunitario</mark> para defender al organismo frente a las infecciones (0,4 p).",
    "Linfocito: célula del sistema inmunitario que <mark class=\"clave-criterio\">reconoce y puede destruir antígenos</mark> (0,4 p).",
    "Macrófago: célula <mark class=\"clave-criterio\">presentadora de antígenos</mark> o <mark class=\"clave-criterio\">fagocítica</mark> (0,4 p)."
