    "Esquema indicando la <mark class=\"clave-criterio\">interfase</mark> con sus fases (<mark class=\"clave-criterio\">G1, S y G2</mark>) y la <mark class=\"clave-criterio\">mitosis</mark> (0,5 p).",
    "Replicación en la <mark class=\"clave-criterio\">fase S</mark> de la interfase (0,15 p); transcripción y traducción durante la interfase (0,2 p); reparto del material hereditario durante la mitosis (0,15 p).",
    "Representación gráfica en la que se observe cómo varía la <mark class=\"clave-criterio\">cantidad de ADN</mark> durante las etapas del ciclo celular (0,5 p)."
