   "id": "pau2010-e2-b2",
   "block": "Metabolismo",
   "topic": "Tipos de nutrición, ATP y NAD⁺",
   "anio": 2010,
   "hasImg": false,
   "competencial": false,
   "q": "Clasifique los seres vivos según su fuente de carbono [0,2]. Indique en cada uno de los grupos anteriores un proceso anabólico y otro catabólico expresando los productos finales de dichos procesos [0,8]. Clasifique los seres vivos según su fuente de obtención de energía [0,2]. Explique el funcionamiento del ATP en la transferencia de energía y el funcionamiento del NAD⁺ en la transferencia de electrones y protones [0,8].",
   "c": [
    "Fuente de carbono inorgánica (CO₂): <mark class=\"clave-criterio\">autótrofos</mark>; fuente de carbono orgánica (moléculas orgánicas): <mark class=\"clave-criterio\">heterótrofos</mark> (0,2 p).",
    "Autótrofos: <mark class=\"clave-criterio\">fotosíntesis</mark> → C₆H₁₂O₆ (glúcidos), etc.; <mark class=\"clave-criterio\">respiración celular</mark> → ATP, CO₂; glucólisis → piruvato, etc. Heterótrofos: <mark class=\"clave-criterio\">gluconeogénesis</mark> → glucosa; biosíntesis de ácidos grasos → ácidos grasos, etc.; glucólisis → piruvato; <mark class=\"clave-criterio\">β-oxidación</mark> → acetil-CoA, etc. Solo un proceso de cada tipo para cada grupo, a 0,2 p cada uno (0,8 p).",
    "Fuente de energía lumínica (sol): <mark class=\"clave-criterio\">fotótrofos</mark>; fuente de energía química (reacciones): <mark class=\"clave-criterio\">quimiótrofos</mark> (0,2 p).",
    "La formación de ATP por <mark class=\"clave-criterio\">fosforilación de ADP</mark> capta energía de unas reacciones que puede ceder a otras al producirse la <mark class=\"clave-criterio\">hidrólisis del ATP</mark> (ADP + P + energía ↔ ATP) (0,4 p).",
    "El NAD⁺ <mark class=\"clave-criterio\">capta electrones y protones</mark> de algunas moléculas (<mark class=\"clave-criterio\">se reduce</mark>) en reacciones de <mark class=\"clave-criterio\">deshidrogenación</mark> (oxidación-reducción) y los puede <mark class=\"clave-criterio\">ceder a otras moléculas</mark> (0,4 p)."
   ],
