    "Láctica: <mark class=\"clave-criterio\">bacterias</mark>, <mark class=\"clave-criterio\">células musculares</mark>, etc.; alcohólica: <mark class=\"clave-criterio\">levaduras</mark>, células vegetales, etc.; acética: bacterias. Solo dos, a 0,15 p cada una (0,3 p).",
    "La <mark class=\"clave-criterio\">oxidación completa</mark> de la glucosa hasta CO₂ y agua mediante la respiración produce <mark class=\"clave-criterio\">más ATP</mark> que la <mark class=\"clave-criterio\">oxidación parcial</mark> de la glucosa hasta una molécula orgánica mediante la fermentación (0,8 p)."
