   "anio": 2010,
   "hasImg": false,
   "competencial": false,
   "q": "Realice un esquema de una molécula de ADN y una de ARN mensajero [0,6]. Cite otros tipos de ARN existentes [0,3]. Defina los términos transcripción y traducción [0,8]. Indique en qué parte de las células procariótica y eucariótica tienen lugar estos procesos [0,3].",
   "c": [
    "En el esquema del ADN debe quedar recogida la disposición <mark class=\"clave-criterio\">antiparalela</mark> de las dos hebras, la <mark class=\"clave-criterio\">unión entre nucleótidos por el fosfórico</mark> y las <mark class=\"clave-criterio\">bases situadas en el interior</mark> (0,3 p).",
    "En el esquema del ARN solo debe figurar <mark class=\"clave-criterio\">una hebra</mark>, con un <mark class=\"clave-criterio\">extremo 3′ y otro 5′</mark> y los nucleótidos propios del ARN (0,3 p).",
    "Tipos: <mark class=\"clave-criterio\">ARN transferente</mark> y <mark class=\"clave-criterio\">ARN ribosómico</mark>. 0,15 p cada uno (0,3 p).",
    "Transcripción: síntesis de una cadena de cualquier tipo de ARN que tiene la <mark class=\"clave-criterio\">secuencia complementaria</mark> de una cadena de ADN que actúa como <mark class=\"clave-criterio\">molde</mark>. Traducción: proceso por el cual la secuencia de nucleótidos de una molécula de <mark class=\"clave-criterio\">ARNm dirige la síntesis de una cadena polipeptídica</mark>. 0,4 p cada una (0,8 p).",
    "En procariotas, ambos en el <mark class=\"clave-criterio\">citoplasma</mark>; en eucariotas, la transcripción en el <mark class=\"clave-criterio\">núcleo</mark> y la traducción en el citoplasma (0,3 p)."
   ],
