   "id": "pau2010-e3-b1",
   "block": "Biomoléculas",
   "topic": "Estructura secundaria y terciaria de proteínas",
   "anio": 2010,
   "hasImg": false,
   "competencial": false,
   "q": "Describa los dos modelos más comunes de estructura secundaria de las proteínas [1]. Describa la estructura terciaria de las proteínas [0,5]. Explique dos enlaces débiles que intervengan en el mantenimiento de estas estructuras [0,5].",
   "c": [
    "<mark class=\"clave-criterio\">α-hélice</mark>: la cadena polipeptídica se enrolla en forma de hélice gracias a los <mark class=\"clave-criterio\">puentes de hidrógeno entre aminoácidos no consecutivos</mark>; las cadenas laterales de los aminoácidos quedan <mark class=\"clave-criterio\">hacia fuera de la hélice</mark> (0,5 p).",
    "<mark class=\"clave-criterio\">Lámina β</mark>: fragmentos de la misma cadena polipeptídica o de distintas cadenas se disponen en paralelo en forma de línea quebrada, fuelle o <mark class=\"clave-criterio\">zigzag</mark>, unidos por <mark class=\"clave-criterio\">puentes de hidrógeno transversales</mark>; las cadenas laterales se disponen hacia arriba y abajo de la lámina plegada (0,5 p).",
    "Estructura terciaria: plegamientos o enrollamientos de la estructura secundaria producidos por enlaces entre las <mark class=\"clave-criterio\">cadenas laterales de aminoácidos alejados</mark> en la cadena polipeptídica. Es <mark class=\"clave-criterio\">característica de cada proteína</mark> (0,5 p).",
    "Enlaces: <mark class=\"clave-criterio\">puentes de hidrógeno</mark>; <mark class=\"clave-criterio\">fuerzas de Van der Waals</mark>; <mark class=\"clave-criterio\">interacciones hidrofóbicas</mark> (repulsión entre grupos apolares y el agua circundante); <mark class=\"clave-criterio\">fuerzas electrostáticas</mark>. Solo dos, a 0,25 p cada una (0,5 p)."
   ],
