   "q": "<b>A la vista de la imagen, que representa una célula en proceso de división y un cromosoma aislado, conteste las siguientes cuestiones:</b><br>a) Indique a qué tipo de división celular corresponde [0,1]. Exponga una razón en la que se basa para responder a la pregunta anterior [0,4]. ¿Qué fases de la división se muestran? [0,1]. Exponga las razones en las que se basa para responder a la pregunta anterior [0,4].<br>b) Indique el nombre de las estructuras o elementos señalados con números [0,7]. ¿Cuál es la causa de que en la estructura número 7 del cromosoma se represente un fragmento de distinto color? [0,3].",
