   "q": "<b>En relación con la figura adjunta, conteste las siguientes cuestiones:</b><br>a) Nombre el proceso general que se representa en la imagen [0,2]. Indique la acción que realiza la célula señalada con el número 1 y el tipo de célula de que se trata [0,2]. Cite dos síntomas característicos de este proceso [0,2]. Describa la acción señalada con el número 2 [0,4].<br>b) Explique las consecuencias de la vasodilatación [0,5]. Indique si este proceso forma parte de las defensas específicas o inespecíficas [0,5].",
