    "b) La vasodilatación aumenta el <mark class=\"clave-criterio\">riego sanguíneo</mark> y la afluencia de <mark class=\"clave-criterio\">glóbulos blancos y moléculas defensivas</mark> a la zona afectada. El enrojecimiento se produce por el aumento de la cantidad de sangre en la zona (0,5 p).",
