   "id": "pau2010-e4-b6",
   "block": "Genética",
   "topic": "Expresión génica: transcripción y traducción",
   "anio": 2010,
   "hasImg": true,
   "competencial": true,
   "q": "<b>A la vista de la imagen, conteste las siguientes cuestiones:</b><br>a) ¿Qué nombre reciben las moléculas señaladas con números? [0,3]. ¿Cómo se denominan los procesos indicados con letras? [0,3]. Defina el proceso indicado con la letra C [0,4].<br>b) ¿Qué orgánulos están implicados en el proceso representado con la letra C? [0,2]. Defina codón [0,5]. ¿Podría darse en sentido inverso alguno de los procesos representados con las letras A, B o C? Explique su respuesta [0,3].",
   "c": [
    "a) Moléculas: 1, <mark class=\"clave-criterio\">ADN</mark>; 2, <mark class=\"clave-criterio\">ARNhn o ARNm</mark>; 3, <mark class=\"clave-criterio\">proteína</mark> (0,3 p).",
    "a) Procesos: A, <mark class=\"clave-criterio\">transcripción</mark>; B, <mark class=\"clave-criterio\">salida del núcleo</mark> del ARNhn o ARNm (maduración); C, <mark class=\"clave-criterio\">traducción</mark> o síntesis de proteínas (0,3 p).",
    "a) Traducción: proceso por el cual la <mark class=\"clave-criterio\">secuencia de nucleótidos</mark> de una molécula de ARNm dirige la síntesis de una <mark class=\"clave-criterio\">cadena polipeptídica</mark> (0,4 p).",
    "b) Orgánulos: <mark class=\"clave-criterio\">ribosomas y retículo endoplasmático rugoso</mark> (0,2 p).",
    "b) Codón: grupo de <mark class=\"clave-criterio\">tres bases del ARNm</mark> (triplete) que <mark class=\"clave-criterio\">codifica un aminoácido</mark> (0,5 p).",
    "b) Gracias a la <mark class=\"clave-criterio\">transcriptasa inversa</mark> puede invertirse la transcripción y sintetizarse una cadena de ADN a partir de un molde de ARN monocatenario (0,3 p)."
   ],
