   "anio": 2010,
   "hasImg": false,
   "competencial": false,
   "q": "Defina triacilglicérido [0,4] y explique dos de sus funciones biológicas [0,6]. Explique cómo obtendría jabón a partir de estas biomoléculas [0,4]. Cite dos biomoléculas hidrófobas insaponificables y una función de cada una de ellas [0,6].",
