    "Con <mark class=\"clave-criterio\">hidróxido sódico o potásico</mark> se <mark class=\"clave-criterio\">hidrolizan los enlaces éster</mark> y se obtienen sales sódicas o potásicas de los ácidos grasos, que son los <mark class=\"clave-criterio\">jabones</mark> (0,4 p).",
    "<mark class=\"clave-criterio\">Colesterol</mark>, <mark class=\"clave-criterio\">esteroides</mark>, etc. Solo dos, a 0,1 p cada una (0,2 p).",
    "Colesterol: <mark class=\"clave-criterio\">componente de membranas</mark>, <mark class=\"clave-criterio\">precursor de hormonas</mark>; esteroides: componentes de membrana, precursores de hormonas, etc. Una función por ejemplo, a 0,2 p (0,4 p)."
