   "id": "pau2010-e6-a2",
   "block": "Genética",
   "topic": "Leyes de Mendel y cruzamiento prueba",
   "anio": 2010,
   "hasImg": false,
   "competencial": false,
   "q": "Enuncie las Leyes de Mendel realizando un esquema [1,2]. Explique en qué consiste el cruzamiento prueba y realice un esquema del mismo [0,8].",
   "c": [
    "Ley de la <mark class=\"clave-criterio\">uniformidad</mark> de los híbridos de la primera generación: al cruzar dos razas puras que difieren en un carácter, los descendientes de la <mark class=\"clave-criterio\">F1</mark> son todos iguales entre sí (fenotipo y genotipo) e iguales en fenotipo a uno de los parentales (0,4 p).",
    "Ley de la <mark class=\"clave-criterio\">separación o disyunción</mark> de los alelos: al cruzar los híbridos de la F1 se obtiene en la F2 una proporción fenotípica <mark class=\"clave-criterio\">3:1</mark> y reaparece el carácter que había desaparecido, porque los alelos se separan sin sufrir modificaciones (0,4 p).",
    "Ley de la <mark class=\"clave-criterio\">segregación independiente</mark>: los alelos de caracteres distintos se transmiten de manera independiente y <mark class=\"clave-criterio\">se combinan al azar</mark> (0,4 p).",
    "Cruzamiento prueba: cruce de un individuo de <mark class=\"clave-criterio\">fenotipo dominante</mark> con un <mark class=\"clave-criterio\">homocigótico recesivo</mark> para averiguar el genotipo del primero. Esquema (basta uno): <mark class=\"clave-criterio\">aa × AA → 100 % dominante</mark>; <mark class=\"clave-criterio\">aa × Aa → 50 % dominante y 50 % recesivo</mark> (0,8 p)."
   ],
