   "id": "pau2011-e1-a6",
   "block": "Microbiología",
   "topic": "Ciclo de vida del VIH",
   "anio": 2011,
   "hasImg": true,
   "competencial": true,
   "q": "<b>El siguiente esquema representa el ciclo de vida del Virus de Inmunodeficiencia Humana (VIH). Conteste las siguientes cuestiones:</b><br>a) Indique cuatro componentes de este virus [0,4]. ¿Qué tipo de ácido nucleico posee? [0,2]. Indique qué representan en el esquema los números 1 y 2 [0,2]. Nombre el tipo de célula a la que infecta [0,2].<br>b) Comente uno a uno los procesos que tienen lugar desde el número 3 hasta el 8 [1].",
   "c": [
    "a) Componentes: <mark class=\"clave-criterio\">bicapa fosfolipídica</mark>, <mark class=\"clave-criterio\">proteínas transmembranales</mark>, <mark class=\"clave-criterio\">glucoproteínas</mark> externas, envuelta proteica interna, nucleoide, ácido nucleico, <mark class=\"clave-criterio\">retrotranscriptasa</mark>, etc. Solo cuatro, a 0,1 p (0,4 p).",
    "a) <mark class=\"clave-criterio\">ARN monocatenario</mark> (0,2 p).",
    "a) 1: <mark class=\"clave-criterio\">contacto con la célula hospedadora</mark>; 2: <mark class=\"clave-criterio\">entrada del ARN vírico</mark> en la célula (0,2 p).",
    "a) <mark class=\"clave-criterio\">Linfocitos T</mark> (0,2 p).",
    "b) 3: la <mark class=\"clave-criterio\">transcriptasa inversa</mark> copia el ARN vírico a ADN (0,2 p); 4: el ADN vírico entra en el núcleo y <mark class=\"clave-criterio\">se inserta en el ADN de la célula</mark> (0,2 p); 5: <mark class=\"clave-criterio\">transcripción</mark> que produce ARN vírico (0,2 p); 6: <mark class=\"clave-criterio\">traducción</mark> que produce proteínas víricas (0,2 p); 7: <mark class=\"clave-criterio\">ensamblaje</mark> del virus (0,1 p); 8: los viriones salen por <mark class=\"clave-criterio\">gemación</mark> (0,1 p)."
   ],
