    "Propiedades: elevada <mark class=\"clave-criterio\">cohesión-adhesión</mark>, elevado <mark class=\"clave-criterio\">calor específico</mark>, elevado <mark class=\"clave-criterio\">calor de vaporización</mark>, <mark class=\"clave-criterio\">baja densidad en estado sólido</mark>, elevada <mark class=\"clave-criterio\">constante dieléctrica</mark>, bajo grado de ionización. Solo cinco, a 0,1 p (0,5 p).",
