    "Hipotónico: el medio externo tiene <mark class=\"clave-criterio\">menor concentración de solutos</mark> que el interno; hipertónico: el medio externo tiene <mark class=\"clave-criterio\">mayor concentración de solutos</mark>. 0,25 p cada uno (0,5 p)."
