   "id": "pau2011-e4-a6",
   "block": "Inmunología",
   "topic": "Opsonización y fagocitosis",
   "anio": 2011,
   "hasImg": true,
   "competencial": true,
   "q": "<b>En relación con la figura adjunta, conteste las siguientes cuestiones:</b><br>a) Identifique las células o moléculas señaladas con números [0,3]. Nombre el proceso que transcurre en la imagen de la derecha [0,2]. Explique lo que sucede desde que la célula número 1 queda recubierta por las partículas número 2 hasta que es incorporada totalmente por la célula 3 [0,5].<br>b) Indique la importancia de este proceso para el organismo [0,4]. ¿Qué células producen la molécula señalada con el número 2? [0,2]. Describa la estructura de dicha molécula [0,4].",
   "c": [
    "a) 1: <mark class=\"clave-criterio\">bacteria, virus o partícula antigénica</mark>; 2: <mark class=\"clave-criterio\">anticuerpo o inmunoglobulina</mark>; 3: <mark class=\"clave-criterio\">macrófago</mark> y/o <mark class=\"clave-criterio\">neutrófilo</mark> (0,3 p).",
    "a) Proceso: <mark class=\"clave-criterio\">fagocitosis</mark> (0,2 p).",
    "a) El macrófago reconoce la partícula mediante la unión de sus <mark class=\"clave-criterio\">receptores con el dominio constante del anticuerpo</mark>; después se produce la <mark class=\"clave-criterio\">invaginación de la membrana</mark>, que se cierra formando el <mark class=\"clave-criterio\">fagosoma</mark>, donde la partícula será digerida (0,5 p).",
    "b) <mark class=\"clave-criterio\">Mecanismo de defensa frente a patógenos</mark> (0,4 p).",
    "b) <mark class=\"clave-criterio\">Linfocitos B</mark> (0,2 p).",
    "b) Estructura: <mark class=\"clave-criterio\">dos cadenas ligeras y dos pesadas</mark> (0,2 p); <mark class=\"clave-criterio\">región constante</mark> (0,1 p); <mark class=\"clave-criterio\">región variable</mark> (0,1 p)."
   ],
